import java.util.Arrays;
import java.util.List;
import java.util.TreeSet;
import java.util.stream.Collectors;

public class Main {
    public static void main(String[] args) {
        List<String> pembeli = Arrays.asList("Sari", "Budi", "Sari", "Andi", "Budi");

        List<String> semua = pembeli.stream().collect(Collectors.toList());
        System.out.println(semua);

        TreeSet<String> unik = pembeli.stream()
                .collect(Collectors.toCollection(TreeSet::new));
        System.out.println(unik);

        String gabung = unik.stream().collect(Collectors.joining(", "));
        System.out.println("Pembeli: " + gabung);

        String kurung = unik.stream().collect(Collectors.joining(" | ", "[", "]"));
        System.out.println(kurung);
    }
}

